export const START="2026-11-24";
export const Q=[{"t":"Valves","q":"Which valve should you never use to throttle flow?","o":["Gate valve","Globe valve","Needle valve","Butterfly valve"],"a":0,"e":"A gate valve is made to be fully open or fully shut. Part-open, flow squeezes under the wedge and wears the seats until it leaks. Throttle with a globe valve.","g":"gate-vs-globe-valve.html","gl":null,"k":"valves.html","n":1},{"t":"Pipe","q":"What is the outside diameter of NPS 6 pipe?","o":["168.3 mm","160.0 mm","165.1 mm","152.4 mm"],"a":0,"e":"NPS 6 pipe is 168.3 mm (6.625 in) outside diameter for every schedule. Only the wall changes.","g":"pipe-schedule-40-vs-80.html","gl":null,"k":"pipe.html","n":2},{"t":"Flanges","q":"Does Sch 80 pipe need a bigger flange than Sch 40 of the same NPS?","o":["No, the OD is the same so the flange fits","Only in Class 300 and above","Yes, one size up","Only for slip-on flanges"],"a":0,"e":"The outside diameter does not change with schedule, so the same flange fits. Only the bore of a weld neck must match the wall.","g":"pipe-schedule-40-vs-80.html","gl":null,"k":"flanges.html","n":3},{"t":"Supports","q":"Which support stops pipe movement in every direction?","o":["Guide","Anchor","Rest","Spring hanger"],"a":1,"e":"An anchor fixes the pipe in all directions. Guides allow axial movement, rests only carry weight.","g":"pipe-shoe-guide-anchor.html","gl":null,"k":"pipe-supports.html","n":4},{"t":"Testing","q":"What is the minimum hydrotest pressure under ASME B31.3?","o":["1.5 × design pressure, corrected for temperature","2 × design pressure","1.1 × design pressure","Equal to design pressure"],"a":0,"e":"B31.3 asks for at least 1.5 times the design pressure, raised by the ratio of allowable stress at test and design temperature.","g":"hydrotest-pressure-b31-3.html","gl":null,"k":"hydrotest-pressure.html","n":5},{"t":"Instruments","q":"Where should a pressure tap go on a horizontal gas line?","o":["On the bottom","On the side, below centre","On the top","Anywhere"],"a":2,"e":"From the top, so any liquid that condenses drains back into the pipe instead of sitting in the impulse line.","g":"pressure-tapping-points.html","gl":null,"k":"instrument-tag-decoder.html","n":6},{"t":"Fittings","q":"What is the centre-to-end of a long-radius 90° elbow?","o":["1.5 × NPS","3 × NPS","1 × NPS","2 × NPS"],"a":0,"e":"A long-radius elbow has a centre-to-end of 1.5 times the nominal size in inches, for NPS ¾ and above. Short radius is 1 × NPS.","g":"long-radius-vs-short-radius-elbow.html","gl":null,"k":"butt-weld-fittings.html","n":7},{"t":"Flanges","q":"Which flange is preferred for high-stress or cyclic service?","o":["Weld neck","Threaded","Lap joint","Slip-on"],"a":0,"e":"The weld neck has a tapered hub and one full butt weld, so it handles bending and fatigue far better than a slip-on.","g":"weld-neck-vs-slip-on-flange.html","gl":null,"k":"flanges.html","n":8},{"t":"Instruments","q":"What does FIC stand for on a P&ID?","o":["Field instrument cable","Flow integrating counter","Flow indicating controller","Fire isolation control"],"a":2,"e":"F is flow, I is indicating, C is controller. The number after it is the loop.","g":"pid-valve-symbols.html","gl":null,"k":"instrument-tag-decoder.html","n":9},{"t":"Layout","q":"Where do cable trays usually go on a pipe rack?","o":["Between the pipes","At grade beside the rack","Top tier","Bottom tier"],"a":2,"e":"On the top tier, away from drips from flanges above and less exposed to fire at grade.","g":"cable-trays-on-pipe-rack.html","gl":null,"k":"pipe-rack.html","n":10},{"t":"Valves","q":"Which valve is best for throttling a small line by hand?","o":["Plug valve","Gate valve","Standard ball valve","Globe valve"],"a":3,"e":"A globe valve controls flow smoothly over its whole stroke, which is why it is also used on control valve bypasses.","g":"gate-vs-globe-valve.html","gl":null,"k":"valves.html","n":11},{"t":"Pipe","q":"Going from Sch 40 to Sch 80 on the same NPS changes what?","o":["The flange class","The outside diameter","The wall thickness and the bore","The pipe length"],"a":2,"e":"The OD stays fixed. A heavier schedule adds wall on the inside, so the bore gets smaller.","g":"pipe-schedule-40-vs-80.html","gl":null,"k":"pipe.html","n":12},{"t":"Flanges","q":"How does an RTJ flange seal?","o":["With a metal ring in a machined groove","With an O-ring","With a spiral wound gasket","With a full-face rubber gasket"],"a":0,"e":"Ring-type joint flanges seal with a solid metal ring (oval or octagonal) pressed into grooves in both faces.","g":"rf-vs-rtj-flange.html","gl":null,"k":"gaskets.html","n":13},{"t":"Supports","q":"Why can a rigid rest lose contact when a line gets hot?","o":["The bolts loosen","Thermal growth lifts the pipe off it","The rest softens","Pressure bends the steel"],"a":1,"e":"When nearby equipment and the line grow with heat, the pipe can rise off a rigid rest and its load moves elsewhere. A spring hanger follows the movement.","g":"pipe-shoe-guide-anchor.html","gl":null,"k":"pipe-supports.html","n":14},{"t":"Testing","q":"Is hydrotest pressure the same at the top and bottom of a tall riser?","o":["No, it is higher at the top","No, it is higher at the bottom by the water head","Only if the line is horizontal","Yes, pressure is equal everywhere"],"a":1,"e":"Water adds about 0.98 bar for every 10 m of height, so the low point sees more than the gauge at the top.","g":"hydrotest-pressure-b31-3.html","gl":null,"k":"hydrotest-pressure.html","n":15},{"t":"Instruments","q":"Where should a pressure tap go on a horizontal liquid line?","o":["Anywhere","On the very bottom","On the side, from horizontal to about 45° below","On the top"],"a":2,"e":"From the side, so gas cannot collect in the tap and dirt from the bottom does not block it.","g":"pressure-tapping-points.html","gl":null,"k":"instrument-tag-decoder.html","n":16},{"t":"Electrical","q":"Should you put a bonding jumper across an insulating flange?","o":["Yes, always","No, it would short out the cathodic protection","Only above NPS 12","Only on gas lines"],"a":1,"e":"The insulating joint is there to block cathodic protection current. A jumper defeats it; use a spark gap or surge arrester if protection is needed.","g":"insulating-flange-kit.html","gl":null,"k":"pipe-supports.html","n":17},{"t":"CAD","q":"Which AutoCAD command counts each block in a drawing?","o":["LIST","BCOUNT","DIST","AREA"],"a":1,"e":"BCOUNT, then Enter, reports every block and its count. BricsCAD has it too.","g":null,"gl":null,"k":"cad-commands-piping.html","n":18},{"t":"Flanges","q":"What is the outside diameter of an NPS 2 Class 150 flange?","o":["114.3 mm","152.4 mm","165.1 mm","127.0 mm"],"a":1,"e":"An NPS 2 Class 150 flange is 152.4 mm (6 in) across, with four ⅝ in bolts.","g":"weld-neck-vs-slip-on-flange.html","gl":null,"k":"flanges.html","n":19},{"t":"Valves","q":"What does a check valve do?","o":["Relieves overpressure","Isolates for maintenance","Stops reverse flow","Throttles flow"],"a":2,"e":"A check valve opens with forward flow and closes when flow tries to reverse, for example on a pump discharge.","g":"pid-valve-symbols.html","gl":null,"k":"valves.html","n":20},{"t":"Pipe","q":"For NPS 14 and larger, the NPS number equals what?","o":["The OD in centimetres","The bore in inches","The schedule","The OD in inches"],"a":3,"e":"From NPS 14 up, the nominal size is the actual outside diameter in inches. Below that it is only a name.","g":null,"gl":null,"k":"pipe.html","n":21},{"t":"Fittings","q":"Why are long-radius elbows preferred over short-radius ones?","o":["Socket weld needs them","Lower pressure drop and smoother flow","They are shorter","They are always cheaper"],"a":1,"e":"The gentler bend loses less pressure and erodes less. Short radius is kept for tight spots.","g":"long-radius-vs-short-radius-elbow.html","gl":null,"k":"butt-weld-fittings.html","n":22},{"t":"Supports","q":"What does a guide allow the pipe to do?","o":["Move along its axis but not sideways","Move sideways only","Rotate only","Not move at all"],"a":0,"e":"A guide holds the pipe in line sideways while letting it slide axially as it grows.","g":"pipe-shoe-guide-anchor.html","gl":null,"k":"pipe-supports.html","n":23},{"t":"Layout","q":"About how much does carbon steel pipe grow over 100 m for a 100 °C rise?","o":["About 12 mm","About 120 mm","About 1.2 mm","About 1.2 m"],"a":1,"e":"Carbon steel expands roughly 0.0117 mm per metre per °C, so 100 m × 100 °C gives about 117 mm.","g":"expansion-loop-guided-cantilever.html","gl":null,"k":"expansion-loop.html","n":24},{"t":"Instruments","q":"What is a TW on a P&ID?","o":["Tube wall","Test weld","Thermowell","Temperature wire"],"a":2,"e":"TW is the thermowell, the pocket in the pipe. The temperature element (TE) sits inside it.","g":"thermowell-installation.html","gl":null,"k":"instrument-tag-decoder.html","n":25},{"t":"Flanges","q":"How many bolts does an NPS 4 Class 150 flange have?","o":["6","12","4","8"],"a":3,"e":"Eight bolts of ⅝ in on a 190.5 mm bolt circle.","g":null,"gl":null,"k":"flanges.html","n":26},{"t":"Testing","q":"What is the minimum pneumatic test pressure under ASME B31.3?","o":["1.25 × design pressure","2 × design pressure","1.5 × design pressure","1.1 × design pressure"],"a":3,"e":"A pneumatic test uses at least 110% of design pressure. Air stores much more energy than water, so it needs extra precautions.","g":"hydrotest-pressure-b31-3.html","gl":null,"k":"hydrotest-pressure.html","n":27},{"t":"Valves","q":"Which valve opens or closes with a quarter turn?","o":["Globe valve","Ball valve","Needle valve","Gate valve"],"a":1,"e":"A ball valve turns 90° from open to shut. Gate and globe valves need many turns of the handwheel.","g":"pid-valve-symbols.html","gl":null,"k":"valves.html","n":28},{"t":"Fittings","q":"Which standard covers butt-weld fittings like elbows and tees?","o":["ASME B16.9","ASME B16.5","ASME B16.11","ASME B16.34"],"a":0,"e":"B16.9 covers factory-made wrought butt-welding fittings. B16.11 is socket-weld and threaded, B16.5 is flanges.","g":null,"gl":null,"k":"butt-weld-fittings.html","n":29},{"t":"Instruments","q":"What does LAHH mean?","o":["Level actuator high head","Level alarm high-high","Level analyser hot hold","Line at high height"],"a":1,"e":"L is level, A is alarm, HH is high-high: the second, more urgent high alarm.","g":null,"gl":null,"k":"instrument-tag-decoder.html","n":30},{"t":"Pipe","q":"NPS 2 pipe is which DN?","o":["DN 65","DN 60","DN 50","DN 40"],"a":2,"e":"NPS 2 is DN 50. The DN number is roughly the NPS in millimetres, rounded.","g":null,"gl":null,"k":"pipe.html","n":31},{"t":"Supports","q":"Which support suits a line that moves up and down when it heats up?","o":["Anchor","Rigid rest","Guide","Variable spring hanger"],"a":3,"e":"A variable spring keeps carrying the load while the pipe moves vertically.","g":null,"gl":null,"k":"pipe-supports.html","n":32},{"t":"Flanges","q":"Which bolt size does an NPS 6 Class 150 flange use?","o":["⅝ in","¾ in","⅞ in","1 in"],"a":1,"e":"Eight ¾ in bolts on a 241.3 mm bolt circle.","g":null,"gl":null,"k":"flanges.html","n":33},{"t":"Layout","q":"Why are hot lines needing loops usually put at the outside edge of a rack?","o":["So the loops can be taken out without crossing other lines","To be nearer the cable trays","For better looks","Because they are lighter"],"a":0,"e":"From the edge, a loop can turn up and over or out sideways without clashing with the lines beside it.","g":"expansion-loop-guided-cantilever.html","gl":null,"k":"pipe-rack.html","n":34},{"t":"Instruments","q":"For gas service, where should the transmitter sit relative to the tap?","o":["Below the tap","It does not matter","Level with it","Above the tap"],"a":3,"e":"Above, so condensed liquid drains back to the pipe instead of filling the impulse line.","g":"pressure-tapping-points.html","gl":null,"k":"instrument-tag-decoder.html","n":35},{"t":"Fittings","q":"Socket-weld fittings are usually limited to which sizes on most projects?","o":["NPS 12 and smaller","NPS 6 and smaller","NPS 2 and smaller","Any size"],"a":2,"e":"Most piping specifications use socket weld for small bore, typically NPS 2 and below, and butt weld above.","g":null,"gl":null,"k":"socket-weld-npt.html","n":36},{"t":"Electrical","q":"Do normal bolted flanges need static bonding jumpers?","o":["Usually not: metal bolts conduct enough","Yes, every flange","Only on water lines","Only when painted"],"a":0,"e":"Metal bolts and metallic gaskets conduct well enough. Jumpers are for coated bolts, non-metallic joints, hoses and swivels.","g":"piping-earthing-static-bonding.html","gl":null,"k":"pipe-supports.html","n":37},{"t":"Valves","q":"In a control valve station, what is the bypass valve usually?","o":["Ball valve","Check valve","Globe valve","Gate valve"],"a":2,"e":"A globe valve, because the operator throttles flow by hand on the bypass while the control valve is out.","g":"control-valve-station-layout.html","gl":null,"k":"control-valves.html","n":38},{"t":"Pipe","q":"Which of these is NOT a stainless steel pipe schedule?","o":["Sch 80S","Sch 40S","Sch 120S","Sch 10S"],"a":2,"e":"ASME B36.19 stainless schedules are 5S, 10S, 40S and 80S. There is no 120S.","g":null,"gl":null,"k":"pipe.html","n":39},{"t":"CAD","q":"Which command deletes duplicate and overlapping lines?","o":["EXPLODE","AUDIT","PURGE","OVERKILL"],"a":3,"e":"OVERKILL removes doubled and overlapping objects. PURGE removes unused layers and blocks.","g":null,"gl":null,"k":"cad-commands-piping.html","n":40},{"t":"Supports","q":"What is a pipe shoe for?","o":["Measuring flow","Draining the line","Lifting the pipe off the steel so insulation can pass","Isolating cathodic protection"],"a":2,"e":"The shoe raises the pipe so the insulation is not crushed, and it slides on the support steel.","g":"pipe-shoe-guide-anchor.html","gl":null,"k":"shoe-spool-length.html","n":41},{"t":"Instruments","q":"A small line is too short for a thermowell. What is a common fix?","o":["Put it on the outside of the pipe","Cut the well short","Fit the well in an elbow, pointing into the flow","Use two wells"],"a":2,"e":"In an elbow the well can point along the pipe and get its full immersion. Enlarging the line locally also works.","g":"thermowell-installation.html","gl":null,"k":"instrument-tag-decoder.html","n":42},{"t":"Flanges","q":"Which standard covers flanges above NPS 24?","o":["ASME B16.9","ASME B16.11","ASME B16.5","ASME B16.47"],"a":3,"e":"B16.5 stops at NPS 24. Larger flanges, NPS 26 to 60, are in B16.47 Series A or B.","g":null,"gl":null,"k":"large-flanges.html","n":43},{"t":"Testing","q":"Before hydrotest, what should you do with spring hangers?","o":["Lock them so they do not move under the water weight","Leave them free","Remove them","Set them to the hot load"],"a":0,"e":"A water-filled line is far heavier than in service, so springs are pinned during the test and released afterwards.","g":"hydrotest-pressure-b31-3.html","gl":null,"k":"pipe-supports.html","n":44},{"t":"Valves","q":"On a P&ID, what does a valve drawn with a filled (solid) body usually mean?","o":["Normally closed","Globe valve","Check valve","Control valve"],"a":0,"e":"Most legends show a normally closed valve with a filled body. Always check the project legend sheet.","g":"pid-valve-symbols.html","gl":null,"k":"pid-symbols.html","n":45},{"t":"Pipe","q":"Up to which size are STD wall and Sch 40 identical?","o":["NPS 2","NPS 10","NPS 24","NPS 4"],"a":1,"e":"Through NPS 10, STD and Sch 40 have the same wall. From NPS 12, STD is thinner (9.53 mm).","g":null,"gl":null,"k":"pipe.html","n":46},{"t":"Fittings","q":"How is an eccentric reducer usually fitted on a pump suction?","o":["Flat side up","Flat side down","Either way","Only on vertical lines"],"a":0,"e":"Flat side up, so no air pocket can form at the top that would make the pump cavitate.","g":null,"gl":null,"k":"butt-weld-fittings.html","n":47},{"t":"Layout","q":"On an isometric, how do you get a pipe cut length?","o":["Use the bend radius only","Add the fittings to the dimension","Measure the drawing with a ruler","Take the dimension and subtract fitting take-outs and weld gaps"],"a":3,"e":"Isometrics are not to scale. Start from the dimension and subtract each fitting’s centre-to-end and the root gaps.","g":"how-to-calculate-pipe-cut-length.html","gl":null,"k":"cut-length.html","n":48},{"t":"Instruments","q":"In an instrument tag, what does the first letter tell you?","o":["The plant area","The measured variable","The function","The loop number"],"a":1,"e":"The first letter is what is measured: P pressure, T temperature, F flow, L level.","g":null,"gl":null,"k":"instrument-tag-decoder.html","n":49},{"t":"Electrical","q":"What are insulating flange kits mainly used for?","o":["Insulating hot lines","Reducing noise","Isolating a cathodically protected buried line from plant piping","Sealing RTJ flanges"],"a":2,"e":"They stop the protection current on a buried pipeline from draining into the earthed plant piping.","g":"insulating-flange-kit.html","gl":null,"k":"flanges.html","n":50},{"t":"Supports","q":"What is a trunnion support?","o":["A short pipe welded to an elbow that rests on a support","A type of valve","A spring hanger","A flange type"],"a":0,"e":"A trunnion is a stub of pipe welded to an elbow or pipe that carries the line down to a support or base plate.","g":"trunnion-support.html","gl":null,"k":"pipe-supports.html","n":51},{"t":"CAD","q":"What is the default AutoCAD alias for OFFSET?","o":["O","OFF","OS","OF"],"a":0,"e":"O runs OFFSET. BricsCAD uses the same alias.","g":null,"gl":null,"k":"cad-commands-piping.html","n":52},{"t":"Flanges","q":"As design temperature rises, a flange’s allowable pressure…","o":["Doubles above 200 °C","Goes up","Stays the same","Goes down"],"a":3,"e":"Steel weakens with temperature, so the B16.5 pressure–temperature ratings fall as temperature rises.","g":null,"gl":null,"k":"pt-ratings.html","n":53},{"t":"Valves","q":"Why are drains fitted between the block valves and a control valve?","o":["To empty and depressure the trapped section before removing it","Only for hydrotest","To measure flow","To vent gas in normal operation"],"a":0,"e":"With both block valves shut, the drains let maintenance empty and depressure the section before opening it up.","g":"control-valve-station-layout.html","gl":null,"k":"control-valves.html","n":54},{"t":"Testing","q":"How much does water head add for every 10 m of height?","o":["About 1 bar","About 10 bar","About 5 bar","About 0.1 bar"],"a":0,"e":"10 m of water is about 0.98 bar, so tall risers need the bottom checked as well as the top.","g":"hydrotest-pressure-b31-3.html","gl":null,"k":"hydrotest-pressure.html","n":55},{"t":"Pipe","q":"What is the wall thickness of NPS 6 Sch 40?","o":["8.18 mm","7.11 mm","10.97 mm","6.02 mm"],"a":1,"e":"NPS 6 Sch 40 is 7.11 mm. Sch 80 is 10.97 mm.","g":"pipe-schedule-40-vs-80.html","gl":null,"k":"pipe.html","n":56},{"t":"Instruments","q":"Which standard is used to check thermowells for flow-induced vibration?","o":["API 520","ASME B31.3 only","ISA-5.1","ASME PTC 19.3 TW"],"a":3,"e":"PTC 19.3 TW checks the wake frequency against the well’s natural frequency.","g":"thermowell-installation.html","gl":null,"k":"instrument-tag-decoder.html","n":57},{"t":"Fittings","q":"When welding a socket-weld joint, what gap is left at the bottom of the socket?","o":["About 1.6 mm (1/16 in)","About 6 mm","About 10 mm","No gap"],"a":0,"e":"Pull the pipe back about 1.6 mm before welding so the weld does not crack when the joint heats and grows.","g":null,"gl":null,"k":"socket-weld-npt.html","n":58},{"t":"Layout","q":"What does pipe spacing on a rack usually depend on?","o":["The pipe colour","The larger flange OD plus clearance, or the insulation","The cable trays","Only the smaller pipe"],"a":1,"e":"Lines are spaced so flanges, insulation and access clear each other with a set gap.","g":null,"gl":null,"k":"pipe-spacing.html","n":59},{"t":"Flanges","q":"What is a spectacle blind used for?","o":["Measuring flow","Supporting the pipe","Reducing the line size","Positively isolating a line"],"a":3,"e":"Turned to the blind side it gives positive isolation; turned to the open side the line runs normally.","g":"spectacle-blind-vs-spacer.html","gl":null,"k":"line-blinds.html","n":60},{"t":"Valves","q":"What is a PSV?","o":["Pump suction valve","Process sample valve","Pressure switch valve","Pressure safety valve"],"a":3,"e":"The pressure safety valve opens to protect equipment from overpressure.","g":null,"gl":null,"k":"instrument-tag-decoder.html","n":61},{"t":"Supports","q":"Which pipe needs supports closer together?","o":["All the same","NPS 2 full of water","NPS 12 empty","NPS 12 full of water"],"a":1,"e":"Small pipe is much less stiff, so its allowable span is far shorter even though it carries less.","g":null,"gl":null,"k":"support-spans.html","n":62},{"t":"CAD","q":"Which command turns a vector PDF into editable CAD lines?","o":["EXPORTPDF","PDFIMPORT","PUBLISH","PDFATTACH"],"a":1,"e":"PDFIMPORT converts the PDF; PDFATTACH only shows it as an underlay you can snap to.","g":null,"gl":null,"k":"cad-commands-piping.html","n":63},{"t":"Instruments","q":"A circle inside a square on a P&ID bubble means what?","o":["A PLC","A computer function","A field instrument","A DCS shared display or control"],"a":3,"e":"Circle in a square is the DCS. A plain circle is a discrete instrument, a hexagon a computer, a diamond in a square a PLC.","g":null,"gl":null,"k":"instrument-tag-decoder.html","n":64},{"t":"Fittings","q":"Which standard covers socket-weld and threaded fittings?","o":["ASME B36.10","ASME B16.11","ASME B16.5","ASME B16.9"],"a":1,"e":"B16.11 covers forged socket-weld and threaded fittings.","g":null,"gl":null,"k":"socket-weld-npt.html","n":65},{"t":"Electrical","q":"Which joint usually DOES need a bonding jumper?","o":["A butt weld","A steel threaded coupling","A standard bolted steel flange","A swivel joint or flexible hose"],"a":3,"e":"Swivels, hoses and non-metallic parts can break the electrical path, so they are bonded across.","g":"piping-earthing-static-bonding.html","gl":null,"k":"pipe-supports.html","n":66},{"t":"Layout","q":"Expansion loops on a rack are usually turned where?","o":["Up over the top tier","Down to grade","Into the next unit","Inside a column"],"a":0,"e":"Turning up over the rack keeps the loop clear of the other lines; plan where it crosses the cable trays.","g":"expansion-loop-guided-cantilever.html","gl":null,"k":"expansion-loop.html","n":67},{"t":"Pipe","q":"What is the empty weight per metre of NPS 6 Sch 40 steel pipe?","o":["About 15.1 kg/m","About 42.6 kg/m","About 28.3 kg/m","About 18.6 kg/m"],"a":2,"e":"W = 0.02466 × (OD − t) × t = 0.02466 × (168.3 − 7.11) × 7.11 ≈ 28.26 kg/m.","g":"pipe-schedule-40-vs-80.html","gl":null,"k":"pipe-weight.html","n":68},{"t":"Valves","q":"Where possible, which way should a control valve actuator point on a horizontal line?","o":["Sideways","Up","Down","Any way"],"a":1,"e":"Stem vertical with the actuator up keeps the packing and actuator in their best position and makes removal easier.","g":"control-valve-station-layout.html","gl":null,"k":"control-valves.html","n":69},{"t":"Flanges","q":"Which gasket is most common on raised-face flanges in process service?","o":["Oval ring","Spiral wound","Lens ring","Full-face rubber"],"a":1,"e":"Spiral wound gaskets with inner and outer rings are the usual choice for raised-face process flanges.","g":"rf-vs-rtj-flange.html","gl":null,"k":"gaskets.html","n":70},{"t":"Instruments","q":"Why do flow meters need straight pipe before and after them?","o":["To make room for a bypass","So the flow profile is settled and the reading is accurate","For drainage","So the meter can be removed"],"a":1,"e":"Elbows, valves and reducers disturb the flow. The meter datasheet gives the straight diameters needed.","g":null,"gl":null,"k":"straight-runs.html","n":71},{"t":"Testing","q":"Why are high points vented before a hydrotest?","o":["To drain it faster afterwards","To cool the water","To lower the test pressure","So air escapes and the line fills completely"],"a":3,"e":"Trapped air compresses, stores energy and spoils the test, so vents at high points let it out while filling.","g":"hydrotest-pressure-b31-3.html","gl":null,"k":"hydrotest-pressure.html","n":72},{"t":"CAD","q":"How do you edit many block attribute values in Excel?","o":["XREF, then BIND","ATTOUT, edit, then ATTIN","PURGE, then AUDIT","BURST, then JOIN"],"a":1,"e":"ATTOUT writes the attributes to a text file; after editing in Excel, ATTIN reads them back in.","g":null,"gl":null,"k":"cad-commands-piping.html","n":73},{"t":"Fittings","q":"When is branch reinforcement needed?","o":["On every tee","When the hole for the branch removes more metal than the run can spare","Never under B31.3","Only on plastic pipe"],"a":1,"e":"B31.3 checks the area removed by the opening against the spare thickness available; if short, add a pad or use a stronger fitting.","g":null,"gl":null,"k":"branch-reinforcement.html","n":74},{"t":"Instruments","q":"A level bridle’s bottom connection must be below what?","o":["Grade","The lowest level to be measured","The vessel bottom","The high level"],"a":1,"e":"If it sits above the low-low level, that level can never be seen and the low alarms cannot work.","g":"level-bridle-gauge-glass.html","gl":null,"k":"instrument-tag-decoder.html","n":75},{"t":"Basics","q":"Which code covers process piping in refineries and chemical plants?","o":["ASME B31.1","ASME B31.8","ASME B31.3","ASME B31.4"],"a":2,"e":"B31.3 is process piping. B31.1 is power piping, B31.4 liquid pipelines and B31.8 gas transmission.","g":null,"gl":null,"k":"piping-basics.html","n":76},{"t":"Flanges","q":"B16.47 Series A flanges, compared with Series B, are…","o":["Lighter, with more and smaller bolts","Only for Class 150","Heavier, with fewer and larger bolts","Identical"],"a":2,"e":"Series A (from MSS SP-44) is the heavier pattern with fewer, larger bolts. Series B (from API 605) is lighter with more, smaller bolts.","g":null,"gl":null,"k":"large-flanges.html","n":77},{"t":"Instruments","q":"Is ⅜ in tubing the same as 10 mm tubing?","o":["Only for air service","No, ⅜ in is 9.5 mm and the fittings do not mix","Only in stainless steel","Yes"],"a":1,"e":"⅜ in is 9.53 mm. Inch and metric compression fittings do not seal on each other.","g":"instrument-tubing-sizes-routing.html","gl":null,"k":"instrument-tag-decoder.html","n":78},{"t":"Basics","q":"Why are molten sulphur lines steam-jacketed?","o":["To lower pressure drop","To stop corrosion","For fire protection","Sulphur solidifies if it cools below about 115 °C"],"a":3,"e":"Sulphur melts at about 115 °C, so the jacket keeps it hot enough to flow without freezing in the line.","g":null,"gl":null,"k":"piping-basics.html","n":79},{"t":"Basics","q":"What does a Claus sulphur recovery unit recover?","o":["Hydrogen from water","Diesel from crude","Elemental sulphur from H₂S","Steam from flue gas"],"a":2,"e":"The Claus process turns hydrogen sulphide from the refinery’s gas streams into elemental sulphur.","g":null,"gl":null,"k":"refinery-units.html","n":80},{"t":"Layout","q":"How much spare space is commonly kept on a new pipe rack?","o":["About 20 to 25%","None","About 75%","Double the width"],"a":0,"e":"Most projects reserve roughly a fifth to a quarter of the width for future lines. Check the project specification.","g":null,"gl":null,"k":"pipe-rack.html","n":81},{"t":"Basics","q":"Which refinery unit removes sulphur compounds from products?","o":["Fluid catalytic cracker","Hydrotreater","Crude distillation unit","Coker"],"a":1,"e":"Hydrotreaters react the sulphur compounds with hydrogen to make H₂S, which then goes to the sulphur recovery unit.","g":null,"gl":null,"k":"refinery-units.html","n":82},{"t":"Drawings","q":"How are piping isometrics usually drawn?","o":["As a 3D photo","On 30° axes and not to scale","As an elevation only","Exactly to scale in plan"],"a":1,"e":"Isometrics show the route on three axes; the dimensions, not the drawing scale, carry the lengths.","g":null,"gl":null,"k":"isometric-symbols.html","n":83},{"t":"Instruments","q":"On an instrument bubble, a solid line through the middle means…","o":["Mounted in the main control room, reachable by the operator","Behind the panel","Not installed yet","Mounted in the field"],"a":0,"e":"No line is field mounted, a solid line is the main control room, a dashed line is behind the panel.","g":null,"gl":null,"k":"instrument-tag-decoder.html","n":84},{"t":"Basics","q":"What does a steam trap do?","o":["Measures steam flow","Raises steam pressure","Stops reverse flow","Lets condensate out while keeping steam in"],"a":3,"e":"Traps drain condensate from steam lines and equipment without letting live steam escape.","g":null,"gl":null,"k":"piping-basics.html","n":85},{"t":"Flanges","q":"In a spectacle blind, when is the open (spacer) side in the line?","o":["When the line is isolated","When the line is in service","Never","Only during hydrotest"],"a":1,"e":"Open side in for normal operation, blind side in for positive isolation.","g":"spectacle-blind-vs-spacer.html","gl":null,"k":"line-blinds.html","n":86},{"t":"Fittings","q":"A short-radius elbow has a centre-to-end of…","o":["1 × NPS","2 × NPS","1.5 × NPS","0.5 × NPS"],"a":0,"e":"Short radius is 1 × NPS; long radius is 1.5 × NPS. Short radius is used where space is tight.","g":"long-radius-vs-short-radius-elbow.html","gl":null,"k":"butt-weld-fittings.html","n":87},{"t":"Supports","q":"What are shear lugs welded to the pipe for?","o":["To drain the line","To earth the pipe","To carry axial load into an anchor or guide","To hold insulation"],"a":2,"e":"Lugs welded to the pipe bear against the support steel, so axial forces pass into the structure.","g":"pipe-shoe-guide-anchor.html","gl":null,"k":"pipe-supports.html","n":88},{"t":"Drawings","q":"On a P&ID, what is the line number used for?","o":["Identifying the line and its size, service and spec","The weld count","The pipe length","The drawing revision"],"a":0,"e":"The line number ties the line to its size, fluid, piping class and insulation in the line list.","g":null,"gl":null,"k":"pid-symbols.html","n":89}];
